//! Independent EtherCAT wire fixtures. Expected bytes are written from the
//! protocol WORD layout and M semantics, never generated by the codec under test.
use esop_ethercat_core::wire::{Command, DatagramHeader, FrameBuilder, FrameView, WireError};
use esop_ethercat_core::{
    ControlError, ControlRequestPool, RegisterOperation, RxAddressPolicy, RxExpectation,
    RxIndexError, RxIndexTable, RxResponse, RxWorkingCounterPolicy, ScanController, ScanError,
    ScanPhase, ScanProgress, auto_increment_address, fixed_address,
};

#[test]
fn independent_headers_cover_every_supported_command_and_m_bit() {
    let commands = [
        (Command::Aprd, 0x01),
        (Command::Apwr, 0x02),
        (Command::Aprw, 0x03),
        (Command::Fprd, 0x04),
        (Command::Fpwr, 0x05),
        (Command::Fprw, 0x06),
        (Command::Brd, 0x07),
        (Command::Bwr, 0x08),
        (Command::Brw, 0x09),
        (Command::Lrd, 0x0a),
        (Command::Lwr, 0x0b),
        (Command::Lrw, 0x0c),
        (Command::Armw, 0x0d),
        (Command::Frmw, 0x0e),
    ];
    for (command, opcode) in commands {
        // ADP = 0x1234, ADO = 0x0130. Logical commands use the same raw DWORD.
        let golden = [opcode, 0x07, 0x34, 0x12, 0x30, 0x01, 0x02, 0x00, 0x00, 0x00];
        let mut actual = [0xff; 10];
        let mut header = DatagramHeader::new(command, 7, 0x0130_1234, 2);
        header.encode(&mut actual).unwrap();
        assert_eq!(actual, golden);
        assert_eq!(DatagramHeader::decode(&golden).unwrap(), header);
        header.last = false;
        header.encode(&mut actual).unwrap();
        assert_eq!(actual[7], 0x80, "M=1 means another datagram follows");
        assert!(!DatagramHeader::decode(&actual).unwrap().last);
    }
    assert_eq!(fixed_address(0x1234, 0x0130), 0x0130_1234);
    assert_eq!(auto_increment_address(2, 0x0130), 0x0130_fffe);
}

#[test]
fn independent_multi_datagram_golden_and_malformed_boundaries() {
    let mut golden = [0u8; 64];
    golden[..44].copy_from_slice(&[
        0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 1, 2, 3, 4, 5, 6, 0x88, 0xa4, 0x1c, 0x10, 0x01, 0x07,
        0xfe, 0xff, 0x30, 0x01, 0x02, 0x80, 0, 0, 0xaa, 0xbb, 0, 0, 0x05, 0x08, 0x34, 0x12, 0x20,
        0x01, 0x02, 0x00, 0, 0, 0xcc, 0xdd, 0, 0,
    ]);
    let mut actual = [0u8; 64];
    let mut builder = FrameBuilder::new(&mut actual, [0xff; 6], [1, 2, 3, 4, 5, 6]).unwrap();
    builder
        .push(
            Command::Aprd,
            7,
            auto_increment_address(2, 0x0130),
            &[0xaa, 0xbb],
        )
        .unwrap();
    builder
        .push(
            Command::Fpwr,
            8,
            fixed_address(0x1234, 0x0120),
            &[0xcc, 0xdd],
        )
        .unwrap();
    assert_eq!(builder.finish().unwrap(), 64);
    assert_eq!(actual, golden);
    let view = FrameView::parse(&golden).unwrap();
    let datagrams: Vec<_> = view.datagrams().collect::<Result<_, _>>().unwrap();
    assert_eq!(datagrams.len(), 2);
    assert!(!datagrams[0].header.last);
    assert!(datagrams[1].header.last);
    let mut premature_last = golden;
    premature_last[23] = 0;
    assert_eq!(
        FrameView::parse(&premature_last).unwrap_err(),
        WireError::DatagramLengthOutOfBounds
    );
    let mut missing_last = golden;
    missing_last[37] = 0x80;
    assert_eq!(
        FrameView::parse(&missing_last).unwrap_err(),
        WireError::DatagramLengthOutOfBounds
    );
    let mut oversized = golden;
    oversized[22] = 0xff;
    oversized[23] = 0x87;
    assert_eq!(
        FrameView::parse(&oversized).unwrap_err(),
        WireError::DatagramLengthOutOfBounds
    );
}

fn expectation(command: Command, address: u32, wkc: u16) -> RxExpectation {
    RxExpectation {
        generation: 9,
        deadline_ns: 100,
        expected_address: address,
        expected_size: 2,
        expected_type: command as u8,
        expected_wkc: wkc,
    }
}

fn response(command: Command, address: u32, wkc: u16) -> RxResponse {
    RxResponse {
        generation: 9,
        received_at_ns: 99,
        address,
        payload_size: 2,
        command: command as u8,
        working_counter: wkc,
    }
}

#[test]
fn bootstrap_binds_transit_to_wkc_and_both_to_capacity() {
    for (adp, wkc, expected) in [
        (0, 0, Ok(())),
        (8, 8, Ok(())),
        (7, 8, Err(RxIndexError::AddressMismatch)),
        (9, 9, Err(RxIndexError::AddressMismatch)),
    ] {
        let mut table = RxIndexTable::new();
        table
            .arm_with_policies(
                7,
                1,
                expectation(Command::Brd, 0, 8),
                RxWorkingCounterPolicy::UpToExpected,
                RxAddressPolicy::BroadcastCount { max_slaves: 8 },
            )
            .unwrap();
        assert_eq!(
            table
                .validate_and_complete(7, response(Command::Brd, adp, wkc))
                .map(|_| ()),
            expected
        );
    }
    let mut table = RxIndexTable::new();
    table
        .arm_with_policies(
            7,
            1,
            expectation(Command::Brd, 0, 8),
            RxWorkingCounterPolicy::UpToExpected,
            RxAddressPolicy::BroadcastCount { max_slaves: 8 },
        )
        .unwrap();
    assert_eq!(
        table.validate_and_complete(7, response(Command::Brd, 0x0001_0002, 2)),
        Err(RxIndexError::AddressMismatch)
    );
}

#[test]
fn transit_count_is_independent_of_wkc_and_command_aware() {
    let policy = RxAddressPolicy::TransitCount { count: 8 };
    for command in [
        Command::Aprd,
        Command::Apwr,
        Command::Aprw,
        Command::Armw,
        Command::Brd,
        Command::Bwr,
        Command::Brw,
    ] {
        assert!(policy.accepts(command as u8, 0x0130_fffe, 0x0130_0006, 1));
        assert!(!policy.accepts(command as u8, 0x0130_fffe, 0x0130_0005, 1));
        assert!(!policy.accepts(command as u8, 0x0130_fffe, 0x0131_0006, 1));
    }
    for command in [
        Command::Fprd,
        Command::Fpwr,
        Command::Fprw,
        Command::Frmw,
        Command::Lrd,
        Command::Lwr,
        Command::Lrw,
    ] {
        assert!(policy.accepts(command as u8, 0x0130_fffe, 0x0130_fffe, 1));
        assert!(!policy.accepts(command as u8, 0x0130_fffe, 0x0130_0006, 1));
    }
    let mut table = RxIndexTable::new();
    table.arm(7, 1, expectation(Command::Aprd, 0, 1)).unwrap();
    assert_eq!(
        table.validate_and_complete(7, response(Command::Aprd, 8, 1)),
        Err(RxIndexError::AddressMismatch)
    );
}

#[test]
fn control_completion_preserves_payload_on_invalid_wkc_and_checks_transit() {
    let mut pool = ControlRequestPool::<1>::new();
    let handle = pool
        .acquire_with_response_policy(
            7,
            9,
            0,
            RegisterOperation::BroadcastRead,
            &[],
            2,
            100,
            8,
            RxWorkingCounterPolicy::UpToExpected,
            RxAddressPolicy::BroadcastCount { max_slaves: 8 },
        )
        .unwrap();
    let mut frame = [0; 64];
    pool.build_into_buffer(handle, &mut frame, [0xff; 6], [0; 6])
        .unwrap();
    pool.complete(handle, 9, 8, &[0x88, 2], 8).unwrap();
    assert_eq!(pool.get(handle).unwrap().actual_wkc, 8);
    assert_eq!(pool.get(handle).unwrap().expectation().expected_wkc, 8);
    pool.release(handle).unwrap();
    let handle = pool
        .acquire(7, 9, 0, RegisterOperation::Read, &[0xaa, 0xbb], 100)
        .unwrap();
    pool.build_into_buffer(handle, &mut frame, [0xff; 6], [0; 6])
        .unwrap();
    assert_eq!(
        pool.complete(handle, 9, 0, &[0xcc, 0xdd], 2),
        Err(ControlError::WorkingCounterMismatch)
    );
    assert_eq!(pool.get(handle).unwrap().payload(), &[0xaa, 0xbb]);
}

#[test]
fn scan_timeout_and_disappearing_slave_never_look_like_end_of_bus() {
    let mut scan = ScanController::<8>::new(0x1000);
    scan.start(9, 0, 1000, 100).unwrap();
    let count = scan.next_action(1).unwrap().unwrap();
    assert_eq!(count.operation, RegisterOperation::BroadcastRead);
    assert_eq!(
        scan.timeout(count.token, count.deadline_ns),
        Err(ScanError::Timeout)
    );
    assert_eq!(scan.phase(), ScanPhase::Faulted);
    scan.start(10, 200, 1000, 100).unwrap();
    let count = scan.next_action(201).unwrap().unwrap();
    scan.accept(count.token, 10, &[0; 2], 8, 202).unwrap();
    let first = scan.next_action(203).unwrap().unwrap();
    assert_eq!(
        first.address_policy,
        RxAddressPolicy::TransitCount { count: 8 }
    );
    assert_eq!(
        scan.accept(first.token, 10, &[0; 2], 0, 204),
        Err(ScanError::UnexpectedWorkingCounter)
    );
    assert!(scan.records().is_empty());
    scan.start(11, 400, 1000, 100).unwrap();
    let count = scan.next_action(401).unwrap().unwrap();
    scan.accept(count.token, 11, &[0; 2], 0, 402).unwrap();
    let end = scan.next_action(403).unwrap().unwrap();
    assert_eq!(end.position, 0);
    assert_eq!(
        scan.accept(end.token, 11, &[0; 2], 0, 404),
        Ok(ScanProgress::Complete)
    );
}

#[test]
fn cyclic_master_and_dc_freeze_transit_separately_from_access_wkc() {
    use esop_ethercat_core::{
        DcCyclicConfig, DcCyclicSync, DcMonitor, DcSyncWindowConfig, ESC_DC_SYSTEM_DIFF,
        EthercatMaster, FramePlan, MasterConfig, RxMatch,
    };
    let config = MasterConfig::new([0xff; 6], [0; 6]);
    let window = DcSyncWindowConfig::new(14, 8, 2, 100, 1, 1).unwrap();
    let mut plan = FramePlan::<1>::new();
    plan.push(window.datagram_plan()).unwrap();
    let mut master = EthercatMaster::<1, 64>::new_with_bus_transit_count(config, 8);
    let frame = master.acquire_frame(9, 100).unwrap();
    master
        .build_and_arm_frame_from_plan(frame, &plan, &[0; 12])
        .unwrap();
    let entry = master.rx_entry(14);
    assert_eq!(entry.expected_wkc, 2);
    assert_eq!(
        entry.address_policy,
        RxAddressPolicy::TransitCount { count: 8 }
    );
    assert_eq!(entry.expected_address, 0x092c_0000);
    let mut sync = DcCyclicSync::new_with_bus_transit_count(
        DcCyclicConfig::new(0x1000, 13, 0),
        DcMonitor::new(50, 10, 1, 1),
        8,
    )
    .with_sync_window(window)
    .unwrap();
    let mut image = [0; 12];
    sync.prepare(9, 100, &mut image).unwrap();
    // Only two slaves implement this broadcast register, while eight traverse it.
    sync.complete(
        1,
        99,
        RxMatch {
            slot_id: 0,
            generation: 9,
            working_counter: 2,
        },
        DatagramHeader {
            command: Command::Brd,
            index: 14,
            address: 0x092c_0008,
            length: 4,
            last: true,
        },
        &[0; 4],
    )
    .unwrap();
    sync.complete(
        1,
        99,
        RxMatch {
            slot_id: 0,
            generation: 9,
            working_counter: 1,
        },
        DatagramHeader::new(Command::Frmw, 13, fixed_address(0x1000, 0x0910), 8),
        &100u64.to_le_bytes(),
    )
    .unwrap();
    assert_eq!(sync.sync_count(), 1);
    sync.prepare(10, 200, &mut image).unwrap();
    assert!(
        sync.complete(
            2,
            199,
            RxMatch {
                slot_id: 0,
                generation: 10,
                working_counter: 2
            },
            DatagramHeader::new(Command::Brd, 14, fixed_address(2, ESC_DC_SYSTEM_DIFF), 4),
            &[0; 4]
        )
        .is_err()
    );
    assert_eq!(sync.sync_count(), 1);
}

#[test]
fn sii_op_only_metadata_is_never_written_to_esc_activation_reserved_bits() {
    use esop_ethercat_core::{
        OpOnlySyncManagerController, OpOnlySyncManagerError, OpOnlySyncManagerProfile,
    };
    // Literal ESC bytes from register section II 2.14.5: only bits 0,1,6,7
    // are writable. Raw metadata remains available for SII/signature checks.
    for (template, disabled, enabled) in [
        (0x09, 0x00, 0x01),
        (0x29, 0x00, 0x01),
        (0xcb, 0xc2, 0xc3),
        (0xff, 0xc2, 0xc3),
    ] {
        for (enable, physical) in [(false, disabled), (true, enabled)] {
            let mut profile = OpOnlySyncManagerProfile::new();
            profile.add(2, template).unwrap();
            assert_eq!(profile.activation_template(2), Some(template));
            assert_eq!(profile.activation_templates()[2], template);
            let mut controller = OpOnlySyncManagerController::new();
            controller
                .start(0x1234, 9, 100, 10, profile, enable)
                .unwrap();
            let action = controller.next_action(1).unwrap().unwrap();
            assert_eq!(action.payload(), &[physical]);
            let mut pool = ControlRequestPool::<1>::new_with_datagram_indices(&[220]).unwrap();
            let handle = controller.enqueue_pending(&mut pool).unwrap();
            let mut bytes = [0; 64];
            pool.build_into_buffer(handle, &mut bytes, [0xff; 6], [0; 6])
                .unwrap();
            assert_eq!(
                &bytes[16..29],
                &[
                    0x05, 220, 0x34, 0x12, 0x16, 0x08, 0x01, 0, 0, 0, physical, 0, 0
                ]
            );
            assert_eq!(bytes[26] & 0x3c, 0);
            pool.complete(handle, 9, action.address, &[physical], 1)
                .unwrap();
            controller.accept_completed(&mut pool, handle, 2).unwrap();
            let read = controller.next_action(3).unwrap().unwrap();
            // Exact readback rejects reserved/SII bits; it is not masked into
            // a permissive comparison that could hide a wrong register byte.
            assert_eq!(
                controller.accept(read, 9, &[physical | 0x08], 1, 4),
                Err(OpOnlySyncManagerError::ReadbackMismatch)
            );
        }
    }
}
